const lit = s => (s === null || s === undefined) ? 'NULL'
  : "convert_from(decode('" + Buffer.from(String(s), 'utf8').toString('base64') + "','base64'),'UTF8')";
const litJson = o => lit(JSON.stringify(o)) + '::jsonb';
const int = v => { const n = parseInt(v, 10); if (!Number.isFinite(n) || String(n) !== String(v).trim()) throw new Error('inteiro invalido: ' + v); return n; };
const intOuNull = v => (v === null || v === undefined || v === '') ? 'NULL' : String(int(v));
const digitos = s => String(s || '').replace(/[^0-9]/g, '');
const litDate = s => { if (s == null || s === '') return 'NULL';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) throw new Error('data invalida'); return lit(String(s)) + '::date'; };
const arr = a => (Array.isArray(a) && a.length) ? 'ARRAY[' + a.map(lit).join(',') + ']::text[]' : "'{}'::text[]";
const bool = v => (v === true ? 'true' : 'false');
const cfgBool = v => String(v == null ? '' : v).trim().toLowerCase() === 'true';
const cfgInt = (v, min, max, padrao) => { const n = parseInt(String(v == null ? '' : v).trim(), 10);
  return (Number.isFinite(n) && n >= min && n <= max) ? n : padrao; };
const semCifrao = sql => { if (String(sql).includes('$')) throw new Error('SQL com cifrao'); return sql; };
const THIAGO = '5511910441709';
// constantes de build (lib-wf.desligarEnvios troca para false): com os envios desligados nada vai para
// giulia_memoria / giulia_mensagens_agendadas (nenhuma mensagem saiu) e o webhook REAL recusa (so o de teste responde)
const ENVIOS_LIGADOS = true;
const MODO_REAL_LIBERADO = true;

const f = items[0].json || {};
const MAPA = {"Zelle (e-mail ou telefone cadastrado no Zelle)":"pagamento_zelle","Link de pagamento com cartão (começa com https://)":"pagamento_cartao_link","Wire · banco (nome)":"pagamento_wire_banco","Wire · endereço do banco":"pagamento_wire_endereco_banco","Wire · beneficiário (nome da conta)":"pagamento_wire_beneficiario","Wire · endereço do beneficiário":"pagamento_wire_endereco_beneficiario","Wire · routing number (ABA)":"pagamento_wire_routing","Wire · número da conta":"pagamento_wire_conta","Wire · SWIFT/BIC":"pagamento_wire_swift","Wire · observação (uma linha)":"pagamento_wire_observacao"};
const ups = [], ignorados = []; let n = 0, apagados = 0, invalidos = 0;
for (const rotulo of Object.keys(MAPA)) {
  const chave = MAPA[rotulo];
  let v = f[rotulo];
  if (v === undefined || v === null) continue;
  v = String(v).replace(/\s+/g, ' ').trim();
  if (v === '') continue;                               // em branco: mantem o valor atual
  if (v === '-') { v = ''; apagados++; }                 // traco: apaga
  else {
    if (chave === 'pagamento_cartao_link' && !/^https:\/\/[a-z0-9.-]+(\/|$)/i.test(v)) { invalidos++; ignorados.push(rotulo); continue; }
    if (/^pagamento_wire_(routing|conta)$/.test(chave) && !/^[0-9][0-9 -]{3,40}$/.test(v)) { invalidos++; ignorados.push(rotulo); continue; }
    n++;
  }
  ups.push('(' + lit(chave) + ', ' + lit(v) + ')');
}
// so os ROTULOS dos campos ignorados voltam na pagina (nunca o valor digitado)
const campos_ignorados = ignorados.join('; ');
if (!ups.length) return [{ json: { sql: 'SELECT 0 AS atualizados, 0 AS apagados, ' + invalidos + ' AS invalidos, 0 AS linhas, 0 AS wire_ok, 0 AS carimbo, ' + lit(campos_ignorados) + ' AS campos_ignorados;', atualizados: 0, apagados: 0, invalidos } }];
// pagamento_wire recomposto no mesmo comando: as partes vem de "up" (valor novo desta gravacao) ou de hz_config (valor atual),
// porque dentro de um unico comando as CTEs que escrevem nao veem as escritas umas das outras
const partesWire = [[1, 'Bank: ', 'pagamento_wire_banco'], [2, 'Bank address: ', 'pagamento_wire_endereco_banco'], [3, 'Beneficiary: ', 'pagamento_wire_beneficiario'],
  [4, 'Beneficiary address: ', 'pagamento_wire_endereco_beneficiario'], [5, 'Account number: ', 'pagamento_wire_conta'], [6, 'Routing number (ABA): ', 'pagamento_wire_routing'],
  [7, 'SWIFT/BIC: ', 'pagamento_wire_swift'], [8, 'Note: ', 'pagamento_wire_observacao']];
const parte = p => '(' + p[0] + ', ' + lit(p[1]) + ', COALESCE((SELECT u.valor FROM up u WHERE u.chave = ' + lit(p[2]) + '), (SELECT c.valor FROM hz_config c WHERE c.chave = ' + lit(p[2]) + ')))';
const sql = 'WITH up AS (UPDATE hz_config c SET valor = v.valor, atualizado_em = NOW() FROM (VALUES ' + ups.join(', ') + ') AS v(chave, valor) WHERE c.chave = v.chave RETURNING c.chave, c.valor)' +
  ', wire AS (UPDATE hz_config SET valor = COALESCE((SELECT string_agg(t.l || t.v, chr(10) ORDER BY t.o) FROM (VALUES ' + partesWire.map(parte).join(', ') +
  ") AS t(o, l, v) WHERE COALESCE(t.v, '') <> ''), ''), atualizado_em = NOW() WHERE chave = 'pagamento_wire' RETURNING chave)" +
  ", ts AS (UPDATE hz_config SET valor = to_char(NOW() AT TIME ZONE 'America/New_York', 'YYYY-MM-DD HH24:MI'), atualizado_em = NOW() WHERE chave = 'pagamento_atualizado_em' RETURNING chave)" +
  ' SELECT ' + n + ' AS atualizados, ' + apagados + ' AS apagados, ' + invalidos + ' AS invalidos, (SELECT count(*) FROM up)::int AS linhas, (SELECT count(*) FROM wire)::int AS wire_ok, (SELECT count(*) FROM ts)::int AS carimbo, ' + lit(campos_ignorados) + ' AS campos_ignorados;';
return [{ json: { sql: semCifrao(sql), atualizados: n, apagados, invalidos } }];
